struct vector3d { float x, y, z; };
struct rigid_body { char data[0x20]; vector3d pos; };

enum WaveMarkerEnum { WAVE_MarkerFaceTrickZ = 43 };
enum {
	WAVE_REGIONFACE = 3, WAVE_REGIONLIP = 5, WAVE_REGIONLIP2 = 12,
	WAVE_REGIONCHIN = 11, WAVE_REGIONPOCKET = 6, WAVE_REGIONTUBE = 9,
	WAVE_REGIONWOBBLE = 14, WAVE_REGIONWASH = 10
};
enum {
	STATE_LIETOSTAND = 2, STATE_PICKSNAPTURNCYCLE = 46,
	STATE_FLAT_TAKEOFF_WOBBLE = 86, STATE_FACE_SPECIAL_TRICK = 95
};
enum {
	TRICK_SNAP = 3, TRICK_REVERT_CUTBACK = 4, TRICK_TAIL_CHUCK = 6,
	TRICK_GOUGE = 7, TRICK_LAYBACK_SLIDE = 8, TRICK_FACE_SHOVEIT = 9,
	TRICK_HANGTEN = 10, TRICK_DARKSLIDE = 11, TRICK_CHEATERS5 = 12,
	TRICK_SITTER = 13, TRICK_MANUAL = 14, TRICK_HEADSTAND = 15,
	TRICK_CRUZER = 16
};

vector3d *WAVE_GetMarker(WaveMarkerEnum);

class board_controller {
public:
	char data_to_rb[0x34C];
	rigid_body *rb;
	char data_to_wave_region[0xA5C];
	int wave_region;
	int GetWaveRegion() { return wave_region; }
};

class kellyslater_controller {
public:
	char data_to_state[0x30];
	int state;
	board_controller my_board_controller;
	char data_to_special[0xD34];
	bool bSpecialTrick;
	char data_to_new_trick[0x243];
	int newTrick;
	char data_to_trick_queued[0x10];
	bool trick_queued;
	char data_to_perform_snap[0xF7];
	bool perform_snap;

	bool Z_Within_Tube();
	bool DoFaceTrick();
};

bool kellyslater_controller::DoFaceTrick()
{
	float face_z = WAVE_GetMarker(WAVE_MarkerFaceTrickZ)->z;
	int cur_region = my_board_controller.GetWaveRegion();
	bool trick_region = (face_z < my_board_controller.rb->pos.z) &&
						((cur_region == WAVE_REGIONFACE) || (cur_region == WAVE_REGIONLIP) ||
						(cur_region == WAVE_REGIONLIP2) || (cur_region == WAVE_REGIONCHIN) ||
						(cur_region == WAVE_REGIONPOCKET) || (cur_region == WAVE_REGIONTUBE) ||
						(cur_region == WAVE_REGIONWOBBLE) || (cur_region == WAVE_REGIONWASH) ||
						((cur_region == WAVE_REGIONTUBE) && Z_Within_Tube()));

	if ((state == STATE_FLAT_TAKEOFF_WOBBLE) || (state == STATE_LIETOSTAND))
		trick_region = false;

	if (trick_queued && (newTrick == TRICK_SNAP) && (state != STATE_LIETOSTAND))
	{
		trick_queued = false;
		if (trick_region)
		{
			perform_snap = true;
			state = STATE_PICKSNAPTURNCYCLE;
			return true;
		}
		else
			bSpecialTrick = false;
	}
	else if (trick_queued && (newTrick == TRICK_REVERT_CUTBACK) && (state != STATE_LIETOSTAND))
	{
		trick_queued = false;
		if (trick_region)
		{
			perform_snap = true;
			state = STATE_PICKSNAPTURNCYCLE;
			return true;
		}
		else
			bSpecialTrick = false;
	}
	else if (trick_queued && (newTrick == TRICK_TAIL_CHUCK) && (state != STATE_LIETOSTAND))
	{
		trick_queued = false;
		if (trick_region)
		{
			perform_snap = true;
			state = STATE_PICKSNAPTURNCYCLE;
			return true;
		}
		else
			bSpecialTrick = false;
	}
	else if (trick_queued && (newTrick == TRICK_GOUGE) && (state != STATE_LIETOSTAND))
	{
		trick_queued = false;
		if (trick_region)
		{
			perform_snap = true;
			state = STATE_PICKSNAPTURNCYCLE;
			return true;
		}
		else
			bSpecialTrick = false;
	}
	else if (trick_queued && (newTrick == TRICK_LAYBACK_SLIDE) && (state != STATE_LIETOSTAND))
	{
		trick_queued = false;
		if (trick_region)
		{
			perform_snap = true;
			state = STATE_PICKSNAPTURNCYCLE;
			return true;
		}
		else
			bSpecialTrick = false;
	}
	else if (trick_queued && ((newTrick == TRICK_FACE_SHOVEIT) || (newTrick == TRICK_HANGTEN)
				|| (newTrick == TRICK_DARKSLIDE) || (newTrick == TRICK_CHEATERS5) || (newTrick == TRICK_SITTER)
				|| (newTrick == TRICK_MANUAL) || (newTrick == TRICK_HEADSTAND) || (newTrick == TRICK_CRUZER)))
	{
		trick_queued = false;
		state = STATE_FACE_SPECIAL_TRICK;
		return true;
	}

	return false;
}
